extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var history_script = load("res://story/history_manager.gd")
	if not check("history_script_exists", history_script != null, "Lo script res://story/history_manager.gd deve esistere"):
		return

	var hm = history_script.new()
	for i in range(105):
		hm.add_entry("Elena", "Battuta %d" % i)

	var entries: Array = hm.get_entries()
	check("history_max_entries", entries.size() == 100, "Lo storico deve contenere massimo 100 elementi (trovati %d)" % entries.size())
	if entries.size() > 0:
		check("history_pop_front", String(entries[0].get("text", "")) == "Battuta 5", "Il primo elemento dopo 105 inserimenti deve essere 'Battuta 5'")

	hm.clear_history()
	check("clear_history", hm.get_entries().is_empty(), "clear_history() deve svuotare lo storico")
	hm.free()

	var advance_script = load("res://story/advance_controller.gd")
	if not check("advance_script_exists", advance_script != null, "Lo script res://story/advance_controller.gd deve esistere"):
		return

	var ac = advance_script.new()
	ac.mark_line_as_read("res://story/intro.json", 2)
	check("is_line_read_true", ac.is_line_read("res://story/intro.json", 2) == true, "is_line_read deve restituire true per righe lette")
	check("is_line_read_false", ac.is_line_read("res://story/intro.json", 3) == false, "is_line_read deve restituire false per righe non lette")

	var delay_short: float = ac.calculate_auto_delay("Ciao")
	check("delay_short", absf(delay_short - 1.5) < 0.01, "calculate_auto_delay per testo breve deve garantire il minimo 1.5 (restituito %.2f)" % delay_short)
	var delay_long: float = ac.calculate_auto_delay("1234567890123456789012345678901234567890")
	check("delay_long", absf(delay_long - 2.0) < 0.01, "calculate_auto_delay per 40 caratteri deve restituire 2.0 (restituito %.2f)" % delay_long)

	check("stop_skip_read", ac.should_stop_skip("res://story/intro.json", 2, false) == false, "should_stop_skip deve restituire false se la riga è già letta e non è scelta")
	check("stop_skip_unread", ac.should_stop_skip("res://story/intro.json", 3, false) == true, "should_stop_skip deve restituire true per righe mai lette")
	check("stop_skip_choice", ac.should_stop_skip("res://story/intro.json", 2, true) == true, "should_stop_skip deve restituire true per le righe di scelta")
	ac.free()

