class_name HistoryManager
extends Node

const MAX_ENTRIES: int = 100

@export var history_list: VBoxContainer

var _entries: Array[Dictionary] = []


func add_entry(speaker: String, text: String) -> void:
	var entry_data := {
		"speaker": speaker,
		"text": text
	}
	_entries.append(entry_data)
	if _entries.size() > MAX_ENTRIES:
		_entries.pop_front()
	_update_ui()


func _update_ui() -> void:
	if not history_list:
		return

	for child in history_list.get_children():
		child.queue_free()

	for entry in _entries:
		var label := Label.new()
		label.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
		if entry["speaker"].is_empty():
			label.text = entry["text"]
		else:
			label.text = "%s: %s" % [entry["speaker"], entry["text"]]
		history_list.add_child(label)

